    from applied_body_pins pin
    where (select md5(replace(prosrc,E'\r\n',E'\n')) from pg_proc where oid=to_regprocedure(pin.signature)) is distinct from pin.body_md5
    union all
    select 'NEW_FUNCTION_DRIFT', pin.signature
    from new_function_pins pin
    where not exists(select 1 from pg_proc p where p.oid=to_regprocedure(pin.signature) and md5(replace(p.prosrc,E'\r\n',E'\n'))=pin.body_md5 and p.prosecdef=pin.definer and p.proisstrict=pin.strict_function
