      and p.prolang=(select oid from pg_language where lanname=pin.language_name)
      and p.provolatile::text=pin.volatility and p.prokind='f' and p.prorettype=to_regtype(pin.result_type)
      and p.proacl::text=pin.acl and not p.proretset and not p.proleakproof and p.proparallel='u'
      and p.probin is null and p.prosqlbody is null and p.protrftypes is null and p.proallargtypes is null and p.proargmodes is null)
