    select 'LEGACY_REVIEW_FUNCTION_OVERLOAD', 'rpc_submit_agreement_review or rpc_get_my_agreement_review has a second overload'
    where (select count(*) from pg_proc where pronamespace='public'::regnamespace and proname in('rpc_submit_agreement_review','rpc_get_my_agreement_review'))<>2
    union all
    select 'READINESS_DRIFT', 'private.retention_ai_source_ready() differs from the predecessor by more than its one certified literal'
    where not exists(select 1 from pg_proc p, cert c where p.oid=to_regprocedure('private.retention_ai_source_ready()')
      and (length(p.prosrc)-length(replace(p.prosrc,c.certified,'')))=length(c.certified)
      and md5(replace(replace(p.prosrc,E'\r\n',E'\n'),c.certified,'__CERTIFIED_SOURCE__'))='bc85a1a744869abb6441e647b18b2195')
    union all
    select 'PROJECTION_SHA_DRIFT', 'private.data_export_projection_sha_v5()'
    where private.data_export_projection_sha_v5() is distinct from '53848e48d1a01082fcbd1413e4f9210b43153a9eb75e7af2723aa8c40f32b597'
    union all
    select 'COMMENT_TABLE_DRIFT', 'private.agreement_review_comments_v1'
    where (not exists(select 1 from pg_class where oid=to_regclass('private.agreement_review_comments_v1') and relowner='postgres'::regrole and relkind='r' and relpersistence='p'
      and not relispartition and relrowsecurity and relforcerowsecurity and relreplident='d' and reloptions is null and relacl=acldefault('r','postgres'::regrole))
    or exists(select 1 from pg_policies where schemaname='private' and tablename='agreement_review_comments_v1')
    or (select string_agg(attname::text||':'||format_type(atttypid,atttypmod)||':'||attnotnull::text||':'||attidentity::text||':'||attgenerated::text,',' order by attnum)
        from pg_attribute where attrelid=to_regclass('private.agreement_review_comments_v1') and attnum>0 and not attisdropped) is distinct from 'review_id:uuid:true::,author_account_id:uuid:true::,target_account_id:uuid:true::,comment:text:true::,comment_sha256:text:true::,created_at:timestamp with time zone:true::,hidden_at:timestamp with time zone:false::,hidden_reason_code:text:false::'
    or (select pg_get_expr(d.adbin,d.adrelid) from pg_attrdef d join pg_attribute a on a.attrelid=d.adrelid and a.attnum=d.adnum
        where d.adrelid=to_regclass('private.agreement_review_comments_v1') and a.attname='created_at') is distinct from 'clock_timestamp()'
    or (select string_agg(conname::text||':'||contype::text,',' order by conname) from pg_constraint
        where conrelid=to_regclass('private.agreement_review_comments_v1') and contype<>'n' and convalidated and conislocal and conparentid=0) is distinct from 'agreement_review_comments_v1_author_fkey:f,agreement_review_comments_v1_hidden_check:c,agreement_review_comments_v1_parties_check:c,agreement_review_comments_v1_pkey:p,agreement_review_comments_v1_review_fkey:f,agreement_review_comments_v1_sha_check:c,agreement_review_comments_v1_target_fkey:f,agreement_review_comments_v1_text_chars_check:c,agreement_review_comments_v1_text_length_check:c,agreement_review_comments_v1_text_trim_check:c'
    or (select count(*) from pg_constraint where conrelid=to_regclass('private.agreement_review_comments_v1') and contype='f' and confdeltype='r' and confupdtype='a' and confmatchtype='s'
        and confrelid in('private.agreement_reviews'::regclass,'public.app_accounts'::regclass))<>3
    or (select string_agg(indexname::text,',' order by indexname) from pg_indexes where schemaname='private' and tablename='agreement_review_comments_v1') is distinct from 'agreement_review_comments_v1_author_idx,agreement_review_comments_v1_pkey,agreement_review_comments_v1_target_idx'
    or not exists(select 1 from pg_indexes where schemaname='private' and tablename='agreement_review_comments_v1' and indexname='agreement_review_comments_v1_target_idx'
        and indexdef like '%(target_account_id, created_at DESC, review_id DESC)%' and indexdef like '%hidden_at IS NULL%')
    or not exists(select 1 from pg_indexes where schemaname='private' and tablename='agreement_review_comments_v1' and indexname='agreement_review_comments_v1_author_idx' and indexdef like '%(author_account_id)%'))
    union all
    select 'TRIGGER_DRIFT', 'private.agreement_review_comments_v1 triggers'
    where (exists(select 1 from (values
      ('agreement_review_comment_closure_guard_v1','private.closure_guard_owned_write()',7,'4143434f554e5400617574686f725f6163636f756e745f696400'),
      ('agreement_review_comment_mutation_guard_v1','private.guard_review_comment_mutation()',27,'')
    ) q(trigger_name,signature,event_type,argument_hex)
    where not exists(select 1 from pg_trigger t where t.tgrelid=to_regclass('private.agreement_review_comments_v1') and t.tgname=q.trigger_name
      and t.tgfoid=to_regprocedure(q.signature) and t.tgtype=q.event_type and t.tgenabled='O' and not t.tgisinternal
      and encode(t.tgargs,'hex')=q.argument_hex and t.tgqual is null and t.tgconstraint=0
      and not t.tgdeferrable and not t.tginitdeferred and t.tgoldtable is null and t.tgnewtable is null and t.tgparentid=0 and t.tgattr::text=''))
    or (select count(*) from pg_trigger where tgrelid=to_regclass('private.agreement_review_comments_v1') and not tgisinternal)<>2)
