    select 'ROSTER_DRIFT', 'the redaction roster does not end with the comment table or the scope/patch do not cover it'
    where cardinality(private.closure_redaction_relations_v5())<>76
      or (private.closure_redaction_relations_v5())[76] is distinct from 'private.agreement_review_comments_v1'
      or (private.closure_redaction_relations_v5())[75] is distinct from 'public.app_accounts'
      or 'private.agreement_reviews'=any(private.closure_redaction_relations_v5())
      or private.closure_redaction_scope_v5('private.agreement_review_comments_v1') is distinct from 't.author_account_id=$1'
      or private.closure_redaction_patch_v5('private.agreement_review_comments_v1','{}'::jsonb,'00000000-0000-0000-0000-000000000000'::uuid,'00000000-0000-0000-0000-000000000000'::uuid)
