    union all
    select 'RETENTION_CATALOG_DRIFT', 'AGREEMENT_REVIEWS'
    where (select relations from private.closure_dataset_catalog_v5 where data_class='AGREEMENT_REVIEWS') is distinct from array['private.agreement_reviews','private.agreement_review_comments_v1']::text[]
      or (select count(*) from private.retention_data_classes where required and active)<>15
    union all
    select 'EXPORT_CATALOG_DRIFT', 'private.data_export_dataset_catalog()'
    where jsonb_array_length(private.data_export_dataset_catalog())<>52
      or (select v->'fields' from jsonb_array_elements(private.data_export_dataset_catalog()) v where v->>'key'='ownAgreementReviews') is distinct from '["agreementId","createdAt","id","rating","tags","comment"]'::jsonb
      or position('OWN_ACCOUNT_V5_10' in (select prosrc from pg_proc where oid=to_regprocedure('private.data_export_snapshot(uuid,uuid,jsonb,timestamptz)')))=0
      or position('OWN_ACCOUNT_V5_9' in (select prosrc from pg_proc where oid=to_regprocedure('private.data_export_snapshot(uuid,uuid,jsonb,timestamptz)')))<>0
      or position('OWN_ACCOUNT_V5_10' in (select prosrc from pg_proc where oid=to_regprocedure('private.data_export_policy_binding()')))=0
      or position('OWN_ACCOUNT_V5_9' in (select prosrc from pg_proc where oid=to_regprocedure('private.data_export_policy_binding()')))<>0
    union all
    select 'STAR_TABLE_DRIFT', 'private.agreement_reviews is not the unchanged immutable star table'
    where (select string_agg(attname::text||':'||format_type(atttypid,atttypmod)||':'||attnotnull::text||':'||attidentity::text||':'||attgenerated::text,',' order by attnum)
           from pg_attribute where attrelid='private.agreement_reviews'::regclass and attnum>0 and not attisdropped) is distinct from 'id:uuid:true::,agreement_id:uuid:true::,reviewer_account_id:uuid:true::,target_account_id:uuid:true::,rating:integer:true::,tags:text[]:true::,client_request_id:uuid:true::,input_hash:text:true::,created_at:timestamp with time zone:true::'
      or (select md5(string_agg(conname||':'||replace(pg_get_constraintdef(oid),'REFERENCES public.','REFERENCES '),';' order by conname)) from pg_constraint where conrelid='private.agreement_reviews'::regclass) is distinct from 'fe44059a7fa96aeb732ff3459f6865d1'
      or (select string_agg(tgname,',' order by tgname) from pg_trigger where tgrelid='private.agreement_reviews'::regclass and not tgisinternal) is distinct from 'pre_v3_closure_review,pre_v3_review_immutable'
      or (select relacl::text from pg_class where oid='private.agreement_reviews'::regclass) is distinct from '{postgres=arwdDxtm/postgres}'
      or not (select relrowsecurity and relforcerowsecurity from pg_class where oid='private.agreement_reviews'::regclass)
      or (select count(*) from pg_policy where polrelid='private.agreement_reviews'::regclass)<>0
    union all
    select 'COMPOSITE_METADATA_DRIFT', pin.signature
    from composite_pins pin
    where not exists(select 1 from pg_proc p where p.oid=to_regprocedure(pin.signature) and p.proowner='postgres'::regrole and p.proacl::text=pin.acl and coalesce(p.proconfig::text,'')=pin.config and p.prosecdef=pin.definer and p.provolatile::text=pin.volatility
      and p.proisstrict=pin.strict_function and p.prolang=(select oid from pg_language where lanname=pin.language_name) and p.prorettype=to_regtype(pin.result_type) and p.prokind='f')
    union all
    select 'RETENTION_CLASS_DESCRIPTION_DRIFT', 'the description of the retention class AGREEMENT_REVIEWS is not the text this package sets'
    where (select description from private.retention_data_classes where code='AGREEMENT_REVIEWS' and required and active) is distinct from 'Immutable bilateral completed-Agreement reviews and their account-level reputation projection (private.agreement_reviews), plus the optional written comment of a review (private.agreement_review_comments_v1): free text of the author, erased when the author account is closed; this description sets no retention period.'
    union all
    select 'COMMENT_TABLE_PUBLISHED', 'the comment table is in a publication, or a FOR ALL TABLES publication exists: the text could be streamed'
    where exists(select 1 from pg_publication_tables where schemaname='private' and tablename='agreement_review_comments_v1') or exists(select 1 from pg_publication where puballtables)
    union all
    select 'CERTIFICATE_CARDINALITY', 'closure_source_v5 and closure_erasure_source_v5 must hold exactly one row each'
    from cert where source_rows<>1 or erasure_rows<>1
    union all
    select 'CERTIFICATE_NOT_BOUND', 'the certificate, the live digest, the erasure source row, the readiness and the binding must all agree'
    from cert where certified is null or certified is distinct from live_digest or certified is distinct from erasure_sha or ready is distinct from true or bound is distinct from certified
    union all
    select 'CERTIFICATE_NOT_MOVED', 'the certified digest must differ from the pre-D12 DEV value when the chain is DEV (58447d7730e909a0c0e60dd92ef77416af927471bd6f645988448e32c6e3cb46)'
    from cert where certified='58447d7730e909a0c0e60dd92ef77416af927471bd6f645988448e32c6e3cb46'
    union all
    select 'FUNCTION_AUTHORITY_DRIFT', 'a new function is reachable by a role it must not be reachable by, or the table is reachable by a client role'
    where has_function_privilege('anon','private.retention_ai_source_ready()','EXECUTE') or has_function_privilege('authenticated','private.retention_ai_source_ready()','EXECUTE')
      or exists(select 1 from unnest(array['private.guard_review_comment_mutation()','private.review_comment_input_v1(jsonb)','public.rpc_submit_agreement_review_v2(uuid,uuid,jsonb,jsonb,uuid,jsonb)','public.rpc_get_my_agreement_review_v2(uuid)','public.rpc_list_review_comments_v1(uuid,integer,jsonb)','public.rpc_moderate_review_comment_service_v1(uuid,text,text,uuid)']::text[]) x where has_function_privilege('anon',x,'EXECUTE'))
      or exists(select 1 from unnest(array['public.rpc_submit_agreement_review_v2(uuid,uuid,jsonb,jsonb,uuid,jsonb)','public.rpc_get_my_agreement_review_v2(uuid)','public.rpc_list_review_comments_v1(uuid,integer,jsonb)']::text[]) x where not has_function_privilege('authenticated',x,'EXECUTE') or has_function_privilege('service_role',x,'EXECUTE'))
      or exists(select 1 from unnest(array['private.guard_review_comment_mutation()','private.review_comment_input_v1(jsonb)']::text[]) x where has_function_privilege('authenticated',x,'EXECUTE') or has_function_privilege('service_role',x,'EXECUTE'))
      or has_function_privilege('authenticated','public.rpc_moderate_review_comment_service_v1(uuid,text,text,uuid)','EXECUTE') or not has_function_privilege('service_role','public.rpc_moderate_review_comment_service_v1(uuid,text,text,uuid)','EXECUTE')
      or exists(select 1 from unnest(array['anon','authenticated','service_role']) r where has_table_privilege(r,'private.agreement_review_comments_v1','SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER'))
    union all
    select 'RETRIED_SQLSTATE_IN_A_NEW_BODY', 'a new function mentions the SQLSTATE that PostgREST 14 re-executes without end (a deterministic conflict must be PT409; no new body mentions it at all)'
    where exists(select 1 from unnest(array['private.guard_review_comment_mutation()','private.review_comment_input_v1(jsonb)','public.rpc_submit_agreement_review_v2(uuid,uuid,jsonb,jsonb,uuid,jsonb)','public.rpc_get_my_agreement_review_v2(uuid)','public.rpc_list_review_comments_v1(uuid,integer,jsonb)','public.rpc_moderate_review_comment_service_v1(uuid,text,text,uuid)']::text[]) x join pg_proc p on p.oid=to_regprocedure(x) where position('40001' in p.prosrc)>0)
    union all
    select 'CLOSURE_IN_FLIGHT', 'a closure execution is EXECUTING'
    where exists(select 1 from private.closure_executions_v5 where state='EXECUTING')
  )
select jsonb_build_object(
  'unit', 'D12_DEV_POSTFLIGHT',
  'metadataPinsChecked', (select count(*) from metadata_pins),
  'unchangedBodyPinsChecked', (select count(*) from unchanged_body_pins),
  'appliedBodyPinsChecked', (select count(*) from applied_body_pins),
  'newFunctionPinsChecked', (select count(*) from new_function_pins),
  'problems', coalesce((select jsonb_agg(jsonb_build_object('kind',kind,'detail',detail) order by kind,detail) from problems), '[]'::jsonb),
  'certifiedSource', (select certified from cert),
  'liveDigest', (select live_digest from cert),
  'ready', (select ready from cert),
  'erasureBindingMatches', (select bound is not distinct from certified from cert),
  'redactionRelations', cardinality(private.closure_redaction_relations_v5()),
  'exportDatasets', jsonb_array_length(private.data_export_dataset_catalog()),
  'exportProjectionSha', private.data_export_projection_sha_v5(),
  'exportPolicyBindingIsNull', private.data_export_policy_binding() is null,
  'commentRows', (select count(*) from private.agreement_review_comments_v1),
  'retentionClassDescription', (select description from private.retention_data_classes where code='AGREEMENT_REVIEWS'),
  'closureHistoryNamingTheCommentTable', (select count(*) from private.closure_redaction_steps_v5 where relation_name='private.agreement_review_comments_v1'),
  'reviews', (select count(*) from private.agreement_reviews),
  'reviewIdHashBaseline', (select md5(string_agg(id::text||':'||input_hash,',' order by id)) from private.agreement_reviews),
  'authenticatedHasPrivateSchemaUsage', has_schema_privilege('authenticated','private','USAGE'),
  'ledgerRows', (select count(*) from supabase_migrations.schema_migrations),
  'latestLedgerVersion', (select max(version) from supabase_migrations.schema_migrations),
  'serverVersion', current_setting('server_version'),
  'checkedAt', to_char(clock_timestamp() at time zone 'utc', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')
) as postflight;
